const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const headerSecret = headers['x-n8n-deploy-secret'] || headers['X-N8N-Deploy-Secret'];
if ($env.DEPLOY_WEBHOOK_SECRET && headerSecret !== $env.DEPLOY_WEBHOOK_SECRET) {
  throw new Error('Invalid deploy webhook secret');
}
const repo = body.repository?.full_name || $env.DEPLOY_REPO || 'OWNER/REPO';
const ref = body.ref || $env.DEPLOY_BRANCH || 'refs/heads/main';
const branch = ref.replace('refs/heads/', '');
const workflowPath = body.workflow_path || body.workflowPath || $env.DEPLOY_WORKFLOW_PATH || 'staging/personal-productivity-safe.json';
if (!workflowPath.startsWith('staging/') || workflowPath.includes('..') || !/^[A-Za-z0-9._/-]+$/.test(workflowPath)) {
  throw new Error(`Refusing unsafe workflow path: ${workflowPath}`);
}
const fileName = workflowPath.split('/').pop();
const stagingInput = `/files/git/${workflowPath}`;
const productionInput = `/files/git/production/${fileName}`;
const downloadUrl = body.download_url || body.downloadUrl || `https://raw.githubusercontent.com/${repo}/${branch}/${workflowPath}`;
const authHeader = $env.GITHUB_TOKEN ? `-H 'Authorization: Bearer ${$env.GITHUB_TOKEN}' ` : '';
const displayName = fileName.replace(/\.json$/, '').replace(/[-_]/g, ' ');
const hardenJson = `const fs=require('fs');const p=process.argv[1];const n=process.argv[2];const j=JSON.parse(fs.readFileSync(p,'utf8'));j.active=false;j.name=(j.name||n)+' - Staging Candidate';fs.writeFileSync(p,JSON.stringify(j,null,2));`;
const importCommand = [
  `mkdir -p '/files/git/staging'`,
  `curl -fsSL ${authHeader}'${downloadUrl}' -o '${stagingInput}'`,
  `node -e "${hardenJson}" '${stagingInput}' '${displayName}'`,
  `n8n import:workflow --input='${stagingInput}'`
].join(' && ');
const baseUrl = ($env.PUBLIC_N8N_BASE_URL || '').replace(/\/$/, '');
if (!baseUrl) {
  throw new Error('PUBLIC_N8N_BASE_URL is required to build the Telegram approval link');
}
if (!$env.DEPLOY_APPROVAL_TOKEN) {
  throw new Error('DEPLOY_APPROVAL_TOKEN is required');
}
const approvalUrl = `${baseUrl}/webhook/workflow-promote-production?token=${encodeURIComponent($env.DEPLOY_APPROVAL_TOKEN)}&source=${encodeURIComponent(stagingInput)}&target=${encodeURIComponent(productionInput)}&name=${encodeURIComponent(fileName)}`;
const telegramText = [
  'Staging workflow import completed. Review it in n8n before approving production.',
  `Workflow: ${fileName}`,
  `Repo: ${repo}`,
  `Branch: ${branch}`,
  `Source path: ${workflowPath}`
].join('\n');
return [{ json: { repo, branch, workflowPath, fileName, stagingInput, productionInput, downloadUrl, approvalUrl, telegramText, importCommand } }];

const item = $input.first().json;
const query = item.query || {};
if (!$env.DEPLOY_APPROVAL_TOKEN || query.token !== $env.DEPLOY_APPROVAL_TOKEN) {
  throw new Error('Invalid production approval token');
}
const source = query.source;
const target = query.target;
const name = query.name || 'workflow.json';
if (!source?.startsWith('/files/git/staging/') || !target?.startsWith('/files/git/production/') || source.includes('..') || target.includes('..')) {
  throw new Error('Refusing unsafe promotion paths');
}
const displayName = name.replace(/\.json$/, '').replace(/[-_]/g, ' ');
const hardenJson = `const fs=require('fs');const p=process.argv[1];const n=process.argv[2];const j=JSON.parse(fs.readFileSync(p,'utf8'));j.active=false;j.name=(j.name||n).replace(/ - Staging Candidate$/,'')+' - Production Candidate';fs.writeFileSync(p,JSON.stringify(j,null,2));`;
const promoteCommand = [
  `test -f '${source}'`,
  `mkdir -p '/files/git/production'`,
  `cp '${source}' '${target}'`,
  `node -e "${hardenJson}" '${target}' '${displayName}'`,
  `n8n import:workflow --input='${target}'`
].join(' && ');
const telegramText = [
  'Production workflow import completed after approval.',
  `Workflow: ${name}`,
  `Imported file: ${target}`,
  'The imported workflow is forced inactive; activate it manually after final review.'
].join('\n');
return [{ json: { source, target, name, promoteCommand, telegramText, responseText: `Production import queued for ${name}. You can close this page.` } }];
